UPDATE materials SET title_ar='فهرس السلسلة 6 H: إفريقيا الاستوائية الفرنسية', description='وصف ببليوغرافي: فهرس السلسلة 6 H: إفريقيا الاستوائية الفرنسية. فهرس أرشيفي واسع لملفات إفريقيا الاستوائية الفرنسية، يضم مراحل الفتح العسكري، الإدارة، التعليم، الشؤون الإسلامية، الخرائط والمراسلات والملفات الخاصة بتشاد ضمن السلسلة GR 6 H. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='فهرس أرشيفي واسع لملفات إفريقيا الاستوائية الفرنسية، يضم مراحل الفتح العسكري، الإدارة، التعليم، الشؤون الإسلامية، الخرائط والمراسلات والملفات الخاصة بتشاد ضمن السلسلة GR 6 H.', notable_quote='«6 H — Afrique équatoriale française»', quote_page='1', author=COALESCE('Service historique de la Défense',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000010';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000010';
