UPDATE materials SET title_ar='مذبحة الكبكب — أبشة 1917: مضمون الملف والروايات المنشورة', description='ملخص نقدي لمصادر حادثة 1917، مع تنبيه صريح إلى الفرق بين الوثيقة الأصلية والروايات الثانوية.', summary='يجمع ما نُشر عن أحداث الكبكب في أبشة سنة 1917، ويميز بين الملف الأرشيفي غير المرقمن والروايات التاريخية المنشورة التي تصف الوقائع والضحايا.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000011';
