UPDATE materials SET title_ar='الطبيب المفتش العام هنري فورنيال (1866–1932)', description='وصف ببليوغرافي: الطبيب المفتش العام هنري فورنيال (1866–1932). سيرة تاريخية للطبيب العسكري هنري فورنيال ومساره الاستعماري، مع تركيز على خبرته الطبية وصلته ببعثة فورو–لامي ومؤسسة الطب العسكري الفرنسي. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='سيرة تاريخية للطبيب العسكري هنري فورنيال ومساره الاستعماري، مع تركيز على خبرته الطبية وصلته ببعثة فورو–لامي ومؤسسة الطب العسكري الفرنسي.', notable_quote='«Le Médecin-Inspecteur Général Henri Fournial (1866-1932)»', quote_page='1', author=COALESCE('Christian Frachette',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000013';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000013';
