UPDATE materials SET title_ar='دليل أرشيف وزارة الخارجية الفرنسية DAMEAE', description='وصف ببليوغرافي: دليل أرشيف وزارة الخارجية الفرنسية DAMEAE. دليل بحث يشرح بنية أرشيف وزارة أوروبا والشؤون الخارجية، وسلاسل الملفات وأدوات الوصول التي يحتاجها الباحث في تاريخ العلاقات الخارجية والاستعمار. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='دليل بحث يشرح بنية أرشيف وزارة أوروبا والشؤون الخارجية، وسلاسل الملفات وأدوات الوصول التي يحتاجها الباحث في تاريخ العلاقات الخارجية والاستعمار.', notable_quote='«Guide des archives diplomatiques»', quote_page='1', author=COALESCE('Archives diplomatiques / HAL',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000016';
