UPDATE materials SET title_ar='التعليم الإسلامي في إفريقيا السوداء', description='وصف ببليوغرافي: التعليم الإسلامي في إفريقيا السوداء. دراسة مقارنة للتعليم الإسلامي في إفريقيا جنوب الصحراء، ومؤسساته وطرائق نقله وعلاقته بالمدرسة الاستعمارية والتحولات الاجتماعية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='دراسة مقارنة للتعليم الإسلامي في إفريقيا جنوب الصحراء، ومؤسساته وطرائق نقله وعلاقته بالمدرسة الاستعمارية والتحولات الاجتماعية.', notable_quote='«L’enseignement islamique en Afrique noire»', quote_page='1', author=COALESCE('Stefania Gandolfi',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000017';
