UPDATE materials SET title_ar='المقدم الطبي هنري فورنيال وبعثة فورو–لامي', description='وصف ببليوغرافي: المقدم الطبي هنري فورنيال وبعثة فورو–لامي. مقال مصوّر عن الطبيب هنري فورنيال ودوره في بعثة فورو–لامي 1898–1900، يجمع بين السيرة والرحلة الاستعمارية والبعد الطبي في استكشاف الصحراء. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مقال مصوّر عن الطبيب هنري فورنيال ودوره في بعثة فورو–لامي 1898–1900، يجمع بين السيرة والرحلة الاستعمارية والبعد الطبي في استكشاف الصحراء.', notable_quote='«De la terre de la soif, ils font sourdre l’eau ; sur la terre de la mort, ils apportent la vie»', quote_page='32', author=COALESCE('Élisabeth Cazenave',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000038';
