UPDATE materials SET title_ar='من 1909 إلى 1960: شعوب تشاد الشرقي وتحولها في وداي', description='وصف ببليوغرافي: من 1909 إلى 1960: شعوب تشاد الشرقي وتحولها في وداي. أطروحة تاريخية اجتماعية تدرس شعوب تشاد الشرقي وموقعها بين الدول والحدود، وتتابع التحولات التي عرفها وداي من سقوط السلطنة إلى نهاية الحقبة الاستعمارية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='أطروحة تاريخية اجتماعية تدرس شعوب تشاد الشرقي وموقعها بين الدول والحدود، وتتابع التحولات التي عرفها وداي من سقوط السلطنة إلى نهاية الحقبة الاستعمارية.', notable_quote='«De 1909 à 1960, aux confins des États»', quote_page='1', author=COALESCE('Moukhtar Bachar Moukhtar',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000039';
