UPDATE materials SET title_ar='تاريخ العرب في السودان، المجلد الأول', description='وصف ببليوغرافي: تاريخ العرب في السودان، المجلد الأول. عمل تاريخي كلاسيكي يتتبع أصول الجماعات العربية وتوطنها وشبكاتها السياسية في السودان، وهو مرجع مقارن لفهم الصلات بين وداي ودارفور ووادي النيل. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='عمل تاريخي كلاسيكي يتتبع أصول الجماعات العربية وتوطنها وشبكاتها السياسية في السودان، وهو مرجع مقارن لفهم الصلات بين وداي ودارفور ووادي النيل.', notable_quote='«A History of the Arabs in the Sudan»', quote_page='1', author=COALESCE('H. A. MacMichael',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000018';
