UPDATE materials SET title_ar='الرحلات والاكتشافات في شمال ووسط إفريقيا، المجلد الثاني', description='وصف ببليوغرافي: الرحلات والاكتشافات في شمال ووسط إفريقيا، المجلد الثاني. سجل رحلة علمية واسعة عبر الصحراء وحوض تشاد والسودان، يجمع الملاحظات الجغرافية واللغوية والإثنوغرافية والوقائع السياسية التي سجلها بارت في القرن التاسع عشر. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='سجل رحلة علمية واسعة عبر الصحراء وحوض تشاد والسودان، يجمع الملاحظات الجغرافية واللغوية والإثنوغرافية والوقائع السياسية التي سجلها بارت في القرن التاسع عشر.', notable_quote='«Travels and Discoveries in North and Central Africa»', quote_page='1', author=COALESCE('Heinrich Barth',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000019';
