UPDATE materials SET title_ar='الرحلات والاكتشافات في شمال ووسط إفريقيا، المجلد الثالث', description='وصف ببليوغرافي: الرحلات والاكتشافات في شمال ووسط إفريقيا، المجلد الثالث. المجلد الثالث من رحلة بارت، ويضم مواد إضافية عن طرق القوافل والبلدان الواقعة بين النيجر والنيل، بما فيها ملاحظات عن وداي ودارفور والحكم المحلي. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='المجلد الثالث من رحلة بارت، ويضم مواد إضافية عن طرق القوافل والبلدان الواقعة بين النيجر والنيل، بما فيها ملاحظات عن وداي ودارفور والحكم المحلي.', notable_quote='«Travels and Discoveries in North and Central Africa»', quote_page='1', author=COALESCE('Heinrich Barth',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000020';
