UPDATE materials SET title_ar='الرحّل بين التحالفات والصراعات: عرب البطحاء في تشاد (1635–2012)', description='وصف ببليوغرافي: الرحّل بين التحالفات والصراعات: عرب البطحاء في تشاد (1635–2012). أطروحة تاريخية وأنثروبولوجية تتابع عرب البطحاء وأنماط الترحال والرعي والتحالف والصراع منذ القرن السابع عشر، وتربط التحولات المحلية بالدولة والحدود والسياسات الحديثة. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='أطروحة تاريخية وأنثروبولوجية تتابع عرب البطحاء وأنماط الترحال والرعي والتحالف والصراع منذ القرن السابع عشر، وتربط التحولات المحلية بالدولة والحدود والسياسات الحديثة.', notable_quote='«Des transhumants entre alliances et conflits, les Arabes du Batha (Tchad) : 1635-2012»', quote_page='1', author=COALESCE('Zakinet Dangbet',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000021';
