UPDATE materials SET title_ar='الاستعمار الفرنسي والمسألة الإسلامية في تشاد: سلطنة وداي (1895–1946)', description='وصف ببليوغرافي: الاستعمار الفرنسي والمسألة الإسلامية في تشاد: سلطنة وداي (1895–1946). دراسة تاريخية للاستعمار الفرنسي في وداي، تركز على علاقة الإدارة بالقوى الإسلامية والعلماء والسلاطين، وعلى أدوات إخضاع المجال الديني والسياسي حتى 1946. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='دراسة تاريخية للاستعمار الفرنسي في وداي، تركز على علاقة الإدارة بالقوى الإسلامية والعلماء والسلاطين، وعلى أدوات إخضاع المجال الديني والسياسي حتى 1946.', notable_quote='«La Colonisation française et la question musulmane au Tchad»', quote_page='1', author=COALESCE('Mahamat Adoum Doutoum',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000022';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000022';
