UPDATE materials SET title_ar='قواعد عربية دارفور', description='وصف ببليوغرافي: قواعد عربية دارفور. أطروحة لغوية وصفية تبني قواعد عربية دارفور من مادتها الصوتية والصرفية والنحوية، وتناقش صلاتها بعربية شرق تشاد ووداي ضمن لهجات الحزام السوداني. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='أطروحة لغوية وصفية تبني قواعد عربية دارفور من مادتها الصوتية والصرفية والنحوية، وتناقش صلاتها بعربية شرق تشاد ووداي ضمن لهجات الحزام السوداني.', notable_quote='«A grammar of Darfur Arabic»', quote_page='1', author=COALESCE('Caroline Roset',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000023';
