UPDATE materials SET title_ar='السكان المسلمون في تشاد والسلطة السياسية (1946–1975)', description='وصف ببليوغرافي: السكان المسلمون في تشاد والسلطة السياسية (1946–1975). أطروحة تدرس وضع السكان المسلمين وعلاقتهم بالدولة والسلطة السياسية في تشاد من أواخر الاستعمار إلى مرحلة ما بعد الاستقلال. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='أطروحة تدرس وضع السكان المسلمين وعلاقتهم بالدولة والسلطة السياسية في تشاد من أواخر الاستعمار إلى مرحلة ما بعد الاستقلال.', notable_quote='«Les populations musulmanes du Tchad et le pouvoir politique»', quote_page='1', author=COALESCE('Mahamat Saleh Yacoub',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000040';
