UPDATE materials SET title_ar='لمحات عن سوسيولوجيا النخب الوادايّة، المجلد الثاني', description='وصف ببليوغرافي: لمحات عن سوسيولوجيا النخب الوادايّة، المجلد الثاني. الجزء الثاني من دراسة النخب الوادايّة، يعالج استمرارية النفوذ الاجتماعي والسياسي وتحولات النخبة بين السلطنة والإدارة الحديثة. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='الجزء الثاني من دراسة النخب الوادايّة، يعالج استمرارية النفوذ الاجتماعي والسياسي وتحولات النخبة بين السلطنة والإدارة الحديثة.', notable_quote='«Aperçus sur la sociologie des élites ouaddaiennes»', quote_page='1', author=COALESCE('Issa Hassan Khayar',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000024';
