UPDATE materials SET title_ar='لمحات عن سوسيولوجيا النخب الوادايّة، المجلد الأول', description='وصف ببليوغرافي: لمحات عن سوسيولوجيا النخب الوادايّة، المجلد الأول. الجزء الأول من أطروحة النخب الوادايّة، يعرّف بالبنية الاجتماعية والقيادات المحلية وطرق تشكل المكانة في وداي قديمًا وحديثًا. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='الجزء الأول من أطروحة النخب الوادايّة، يعرّف بالبنية الاجتماعية والقيادات المحلية وطرق تشكل المكانة في وداي قديمًا وحديثًا.', notable_quote='«Aperçus sur la sociologie des élites ouaddaiennes»', quote_page='1', author=COALESCE('Issa Hassan Khayar',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000025';
