UPDATE materials SET title_ar='لا شك: العلم الإسلامي والمجتمع في إفريقيا الوسطى السودانية في القرن السابع عشر', description='وصف ببليوغرافي: لا شك: العلم الإسلامي والمجتمع في إفريقيا الوسطى السودانية في القرن السابع عشر. أطروحة تبحث في العلماء والكتب والشبكات الإسلامية في إفريقيا الوسطى السودانية خلال القرن السابع عشر، وتعيد بناء صلة المعرفة بالمجتمع والسلطة في فضاء وداي وما حوله. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='أطروحة تبحث في العلماء والكتب والشبكات الإسلامية في إفريقيا الوسطى السودانية خلال القرن السابع عشر، وتعيد بناء صلة المعرفة بالمجتمع والسلطة في فضاء وداي وما حوله.', notable_quote='«There is no doubt. Muslim scholarship and society in 17th-century Central Sudanic Africa»', quote_page='1', author=COALESCE('Dorrit van Dalen',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000026';
