UPDATE materials SET title_ar='الفتح الاستعماري وترسيم حدود تشاد (1890–1936)', description='وصف ببليوغرافي: الفتح الاستعماري وترسيم حدود تشاد (1890–1936). دراسة تاريخية لمسار التوسع الفرنسي وترسيم الحدود التشادية، وتفحص الحملات والاتفاقات والمصالح الدولية التي أنتجت المجال الترابي الحديث. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='دراسة تاريخية لمسار التوسع الفرنسي وترسيم الحدود التشادية، وتفحص الحملات والاتفاقات والمصالح الدولية التي أنتجت المجال الترابي الحديث.', notable_quote='«Conquête coloniale et délimitation des frontières du Tchad : 1890-1936»', quote_page='1', author=COALESCE('Mahamat Assileck',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000041';
