UPDATE materials SET title_ar='ديناميات الاندماج الوطني: ما بعد الصراع الإثني في دولة قيد التشكل', description='وصف ببليوغرافي: ديناميات الاندماج الوطني: ما بعد الصراع الإثني في دولة قيد التشكل. ورقة تحليلية تنتقد اختزال الأزمة التشادية في ثنائية الشمال والجنوب أو المسلمين والمسيحيين، وتقترح النظر إلى المواطنة وبناء المجال المشترك وتجاوز لغة الانقسام. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='ورقة تحليلية تنتقد اختزال الأزمة التشادية في ثنائية الشمال والجنوب أو المسلمين والمسيحيين، وتقترح النظر إلى المواطنة وبناء المجال المشترك وتجاوز لغة الانقسام.', notable_quote='«Society is not something fixed from the time of its creation; it is constantly in the making and can only be defined in action»', quote_page='1', author=COALESCE('Ladiba Gondeu',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000027';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000027';
