UPDATE materials SET title_ar='أثر الإرث الاستعماري في العلاقات المدنية–العسكرية: تشاد والسودان', description='وصف ببليوغرافي: أثر الإرث الاستعماري في العلاقات المدنية–العسكرية: تشاد والسودان. أطروحة مقارنة تدرس كيف شكّل الإرث الاستعماري مؤسسات الجيش والعلاقة بين المدنيين والعسكريين في تشاد والسودان، مع تحليل مسارات الدولة والانقلابات والصراع على السلطة. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='أطروحة مقارنة تدرس كيف شكّل الإرث الاستعماري مؤسسات الجيش والعلاقة بين المدنيين والعسكريين في تشاد والسودان، مع تحليل مسارات الدولة والانقلابات والصراع على السلطة.', notable_quote='«The impact of the colonial legacy on Civil-Military Relations in Africa»', quote_page='1', author=COALESCE('Mahamoud Adam Bechir',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000042';
DELETE FROM materials_fts WHERE ark='ARC-TD-BOK-000042';
