UPDATE materials SET title_ar='التصوف ودوره في الشعر العربي: الحالة التشادية في شعر عبد الحق الترجمي', description='وصف ببليوغرافي: التصوف ودوره في الشعر العربي: الحالة التشادية في شعر عبد الحق الترجمي. تدرس المقالة أثر التصوف الإسلامي في الشعر العربي التشادي من خلال عبد الحق محمد أحمد الترجمي (1853–1917)، وتربط التجربة الشعرية بالتاريخ الديني والثقافي للطرق الصوفية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تدرس المقالة أثر التصوف الإسلامي في الشعر العربي التشادي من خلال عبد الحق محمد أحمد الترجمي (1853–1917)، وتربط التجربة الشعرية بالتاريخ الديني والثقافي للطرق الصوفية.', notable_quote='«تبحث الدراسة أثر التصوف الإسلامي في تشكيل النتاج الشعري العربي في تشاد، عبر نموذج الشاعر الصوفي عبد الحق محمد أحمد الترجمي»', quote_page='1', author=COALESCE('محمد حبيب الغالي آدم',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000028';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000028';
