UPDATE materials SET title_ar='الصلح في تشاد: التكيف مع الاستعمار', description='وصف ببليوغرافي: الصلح في تشاد: التكيف مع الاستعمار. مسودة بحث تفسر كيف تعامل علماء وداي مع سقوط السلطنة سنة 1909، وتقرأ مفهوم الصلح والتعايش في كتابات عبد الحق السنوسي الترجمي وفي الذاكرة المحلية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مسودة بحث تفسر كيف تعامل علماء وداي مع سقوط السلطنة سنة 1909، وتقرأ مفهوم الصلح والتعايش في كتابات عبد الحق السنوسي الترجمي وفي الذاكرة المحلية.', notable_quote='«In 1909, when the sultanate of Wadai ... succumbed to French authority»', quote_page='1', author=COALESCE('Dorrit van Dalen',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000029';
