UPDATE materials SET title_ar='الدعوة الإسلامية وأثرها في الحياة السياسية بمملكة باقرمي', description='وصف ببليوغرافي: الدعوة الإسلامية وأثرها في الحياة السياسية بمملكة باقرمي. تتناول الدراسة تشكل الدعوة الإسلامية في باقرمي ودورها في بناء المملكة وحمايتها وتطويرها، مع إبراز حضور الدين في الشرعية السياسية والذاكرة التاريخية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تتناول الدراسة تشكل الدعوة الإسلامية في باقرمي ودورها في بناء المملكة وحمايتها وتطويرها، مع إبراز حضور الدين في الشرعية السياسية والذاكرة التاريخية.', notable_quote='«تهدف الدراسة إلى إحياء التراث الإسلامي، وتوضيح الدور الذي قامت به الدعوة الإسلامية في تكوين مملكة باقرمي»', quote_page='1', author=COALESCE('إبراهيم الزين عبد المالك',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000030';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000030';
