UPDATE materials SET title_ar='أثر التعاون التعليمي بين كانم والعالم العربي في تطوير التعليم العربي', description='وصف ببليوغرافي: أثر التعاون التعليمي بين كانم والعالم العربي في تطوير التعليم العربي. تبحث المقالة في صلات كانم بالعالم العربي، وبخاصة مصر، ودورها في انتقال التعليم العربي وتكوين المعرفة والمؤسسات في الفترة الممتدة من القرن الخامس إلى السادس الهجري. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تبحث المقالة في صلات كانم بالعالم العربي، وبخاصة مصر، ودورها في انتقال التعليم العربي وتكوين المعرفة والمؤسسات في الفترة الممتدة من القرن الخامس إلى السادس الهجري.', notable_quote='«The impact of educational cooperation of the relationship between the Kingdom of Kanem and Arab world»', quote_page='1', author=COALESCE('إسماعيل أحمد محمد',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000031';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000031';
