UPDATE materials SET title_ar='الدعوة الإسلامية وأثرها في الحياة الاجتماعية بمملكة باقرمي', description='وصف ببليوغرافي: الدعوة الإسلامية وأثرها في الحياة الاجتماعية بمملكة باقرمي. تتبع الدراسة أثر الإسلام في البنية الاجتماعية والعلاقات والقيم والمؤسسات في باقرمي، وتوضح كيف أسهمت الدعوة في تكوين مجتمع المملكة وتماسكه. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تتبع الدراسة أثر الإسلام في البنية الاجتماعية والعلاقات والقيم والمؤسسات في باقرمي، وتوضح كيف أسهمت الدعوة في تكوين مجتمع المملكة وتماسكه.', notable_quote='«الدعوة الإسلامية وأثرها على الحياة الاجتماعية في مملكة باقرمي»', quote_page='1', author=COALESCE('إبراهيم الزين عبد المالك',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000032';
