UPDATE materials SET title_ar='دور الرماة السنغاليين في احتلال وإدارة إقليم تشاد (1897–1960)', description='وصف ببليوغرافي: دور الرماة السنغاليين في احتلال وإدارة إقليم تشاد (1897–1960). تدرس المقالة مشاركة الرماة السنغاليين في الحملات الفرنسية على تشاد، ثم أدوارهم في تثبيت الاحتلال والإدارة حتى 1960، مع إبراز انتقالهم من القوة المساعدة إلى أداة سيطرة. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تدرس المقالة مشاركة الرماة السنغاليين في الحملات الفرنسية على تشاد، ثم أدوارهم في تثبيت الاحتلال والإدارة حتى 1960، مع إبراز انتقالهم من القوة المساعدة إلى أداة سيطرة.', notable_quote='«تناول البحث دور الرماة السنغاليين في احتلال إقليم تشاد مبينًا مشاركتهم الفاعلة مع الفرنسيين»', quote_page='1', author=COALESCE('آدم الضي محمد؛ إبراهيم حسن السليك',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000044';
DELETE FROM materials_fts WHERE ark='ARC-TD-BOK-000044';
