UPDATE materials SET title_ar='اللغة العربية وأثرها في بناء الهوية الوطنية للشعب التشادي', description='وصف ببليوغرافي: اللغة العربية وأثرها في بناء الهوية الوطنية للشعب التشادي. تبحث الدراسة الجذور التاريخية للعربية في تشاد وصلتها بالهوية الوطنية والثقافة العربية الإسلامية، وتناقش العوائق التي أثرت في حضورها العام والتعليمي. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تبحث الدراسة الجذور التاريخية للعربية في تشاد وصلتها بالهوية الوطنية والثقافة العربية الإسلامية، وتناقش العوائق التي أثرت في حضورها العام والتعليمي.', notable_quote='«تناولت هذه الدراسة موضوع اللغة العربية وأثرها في بناء وصياغة الهوية الوطنية للشعب التشادي»', quote_page='1', author=COALESCE('الطيب إدريس حلولو',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000033';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000033';
