UPDATE materials SET title_ar='اللغة العربية في مملكة وداي – تشاد: دراسة استقرائية وصفية', description='وصف ببليوغرافي: اللغة العربية في مملكة وداي – تشاد: دراسة استقرائية وصفية. دراسة وصفية لتاريخ العربية ووظائفها في مملكة وداي، مع عرض مسارات انتشارها ومكانتها في التعليم والثقافة والإدارة والهوية المحلية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='دراسة وصفية لتاريخ العربية ووظائفها في مملكة وداي، مع عرض مسارات انتشارها ومكانتها في التعليم والثقافة والإدارة والهوية المحلية.', notable_quote='«اللغة العربية في مملكة وداي – تشاد: دراسة استقرائية وصفية»', quote_page='1', author=COALESCE('أحمد إبراهيم حران',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000034';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000034';
