UPDATE materials SET title_ar='المقاومة الوطنية ضد الاستعمار الفرنسي في تشاد (1920–1960): دراسة تاريخية تحليلية', description='وصف ببليوغرافي: المقاومة الوطنية ضد الاستعمار الفرنسي في تشاد (1920–1960): دراسة تاريخية تحليلية. تستعرض الدراسة أشكال مقاومة الممالك والمجتمعات التشادية للاحتلال الفرنسي، وتفسر عوامل القوة والضعف التي أثرت في السيطرة الاستعمارية حتى الاستقلال. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تستعرض الدراسة أشكال مقاومة الممالك والمجتمعات التشادية للاحتلال الفرنسي، وتفسر عوامل القوة والضعف التي أثرت في السيطرة الاستعمارية حتى الاستقلال.', notable_quote='«تناولت هذه الدراسة محور المقاومة الوطنية ضد الاستعمار الفرنسي»', quote_page='1', author=COALESCE('يسرية موسى أحمد جمال الدين',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000035';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000035';
INSERT INTO materials_fts (ark,title,body) SELECT ark,title_ar,trim(coalesce(description,'')||char(10)||coalesce(summary,'')||char(10)||coalesce(notable_quote,'')||char(10)||coalesce(full_text,'')) FROM materials WHERE ark='ARC-TD-DOC-000035';
UPDATE materials SET title_ar='دخول وانتشار الإسلام في تشاد', description='وصف ببليوغرافي: دخول وانتشار الإسلام في تشاد. تقدم المقالة سردًا تحليليًا لدخول الإسلام وانتشاره في تشاد وحوض بحيرة تشاد والسودان الأوسط، وتبرز أثره الحضاري والاجتماعي ودور تشاد بوصفها بوابة إلى إفريقيا جنوب الصحراء. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تقدم المقالة سردًا تحليليًا لدخول الإسلام وانتشاره في تشاد وحوض بحيرة تشاد والسودان الأوسط، وتبرز أثره الحضاري والاجتماعي ودور تشاد بوصفها بوابة إلى إفريقيا جنوب الصحراء.', notable_quote='«تتناول هذه الورقة العلمية دخول الإسلام إلى تشاد وانتشاره وأثره الحضاري في حوض بحيرة تشاد»', quote_page='1', author=COALESCE('آدم أحمد حسن',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000036';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000036';
