UPDATE materials SET title_ar='الإنسانية في الأشعار العربية التشادية التجديدية: دراسة سردية تحليلية', description='وصف ببليوغرافي: الإنسانية في الأشعار العربية التشادية التجديدية: دراسة سردية تحليلية. تحلل الدراسة الأغراض الإنسانية في الشعر العربي التشادي الحديث، وتبحث في حضور قضايا الإنسان والكرامة والمجتمع ضمن التجديد الشعري المحلي. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تحلل الدراسة الأغراض الإنسانية في الشعر العربي التشادي الحديث، وتبحث في حضور قضايا الإنسان والكرامة والمجتمع ضمن التجديد الشعري المحلي.', notable_quote='«الإنسانية ويُقصد بها الأغراض الإنسانية، وهي من الموضوعات التي تطرق إليها الشعر العربي التجديدي»', quote_page='1', author=COALESCE('مولود محمد أبكر؛ أزرق الخليل السيط',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000037';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000037';
