UPDATE materials SET title_ar='علماء وداي ومقاومة الاحتلال الفرنسي: دراسة تاريخية تحليلية', description='وصف ببليوغرافي: علماء وداي ومقاومة الاحتلال الفرنسي: دراسة تاريخية تحليلية. تتناول الدراسة علاقة علماء وداي بالسلطنة ومواقفهم من الاحتلال الفرنسي، وتبرز دور المعرفة الدينية والفتوى والشبكات العلمية في المقاومة والشرعية السياسية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تتناول الدراسة علاقة علماء وداي بالسلطنة ومواقفهم من الاحتلال الفرنسي، وتبرز دور المعرفة الدينية والفتوى والشبكات العلمية في المقاومة والشرعية السياسية.', notable_quote='«علماء وداي ومقاومة الاحتلال الفرنسي»', quote_page='1', author=COALESCE('عبد الواحد محمد داود',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000038';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000038';
