UPDATE materials SET title_ar='علاقة سلطنة دار وداي بالسلطنة العثمانية', description='وصف ببليوغرافي: علاقة سلطنة دار وداي بالسلطنة العثمانية. تبحث المقالة أبعاد العلاقة السياسية والثقافية والاجتماعية بين وداي والدولة العثمانية، وتعرض طرق تشكل الصلات والتمثلات المتبادلة في المصادر التاريخية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تبحث المقالة أبعاد العلاقة السياسية والثقافية والاجتماعية بين وداي والدولة العثمانية، وتعرض طرق تشكل الصلات والتمثلات المتبادلة في المصادر التاريخية.', notable_quote='«The aim of this study is to clarify the extent of the relationship that prevailed between the Sultanate of Ouaddaï and the Ottoman Sultanate»', quote_page='1', author=COALESCE('الصادق أحمد آدم',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000039';
