UPDATE materials SET title_ar='مراجعة أدبية للكتابات العربية الوسيطة عن كانم–برنو', description='وصف ببليوغرافي: مراجعة أدبية للكتابات العربية الوسيطة عن كانم–برنو. مراجعة نقدية لمصادر الجغرافيين والرحالة والمؤرخين العرب عن كانم–برنو، تناقش قيمتها في إعادة بناء التاريخ الإفريقي ومشكلاتها التقنية والمنهجية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مراجعة نقدية لمصادر الجغرافيين والرحالة والمؤرخين العرب عن كانم–برنو، تناقش قيمتها في إعادة بناء التاريخ الإفريقي ومشكلاتها التقنية والمنهجية.', notable_quote='«Arab geographers, travellers, and traders produced a corpus of literary works in Arabic»', quote_page='150', author=COALESCE('Adam Adebayo Sirajudeen؛ Sulayman Adeniran Shittu',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000040';
