UPDATE materials SET title_ar='مخالب الاستعمار على التعليم العربي في إفريقيا: النيجر وتشاد والسنغال نموذجًا', description='وصف ببليوغرافي: مخالب الاستعمار على التعليم العربي في إفريقيا: النيجر وتشاد والسنغال نموذجًا. بحث قصير يناقش أثر الاستعمار في التعليم العربي الإسلامي، ويقارن بين النيجر وتشاد والسنغال من حيث السيطرة اللغوية والمدرسة الثنائية وتحويل التعليم إلى أداة نفوذ. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='بحث قصير يناقش أثر الاستعمار في التعليم العربي الإسلامي، ويقارن بين النيجر وتشاد والسنغال من حيث السيطرة اللغوية والمدرسة الثنائية وتحويل التعليم إلى أداة نفوذ.', notable_quote='«ظهرت الآثار السلبية للاستعمار على اللغة العربية عن طريق إرادة سيطرة اللغة الاستعمارية على اللغات الأخرى في إفريقيا»', quote_page='1', author=COALESCE('إبراهيم محمد جبريل',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000041';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000041';
