UPDATE materials SET title_ar='المكتبة الأكاديمية التشادية — الفهرس الموحّد', description='بوابة وصفية للمجموعة الأكاديمية التشادية، تتضمن الموضوعات واللغات والجامعات وروابط النسخ المفتوحة.', summary='فهرس موحد للرسائل والأبحاث والمقالات عن تشاد ووداي واللغة العربية والإسلام والاستعمار، يميز بين النصوص الكاملة والسجلات الببليوغرافية.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000042';
