UPDATE materials SET title_ar='حياة السلطان رابح: الفرنسيون في تشاد', description='وصف ببليوغرافي: حياة السلطان رابح: الفرنسيون في تشاد. كتاب رحلات وتاريخ عسكري عن رابح الزبير وسقوط سلطته، يصف التقدم الفرنسي في حوض تشاد والصدامات التي أعادت تشكيل المنطقة في مطلع القرن العشرين. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='كتاب رحلات وتاريخ عسكري عن رابح الزبير وسقوط سلطته، يصف التقدم الفرنسي في حوض تشاد والصدامات التي أعادت تشكيل المنطقة في مطلع القرن العشرين.', notable_quote='«La vie du sultan Rabah : les Français au Tchad»', quote_page='1', author=COALESCE('Gaston Dujarric',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000043';
