UPDATE materials SET title_ar='سقوط إمبراطورية رابح', description='وصف ببليوغرافي: سقوط إمبراطورية رابح. شهادة استعمارية عن حملة إميل جنتيل وسقوط دولة رابح سنة 1900، وتوثيق العمليات والمواقع والقوى المتنافسة في حوض تشاد. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='شهادة استعمارية عن حملة إميل جنتيل وسقوط دولة رابح سنة 1900، وتوثيق العمليات والمواقع والقوى المتنافسة في حوض تشاد.', notable_quote='«La chute de l’empire de Rabah»', quote_page='1', author=COALESCE('Émile Gentil',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000044';
