UPDATE materials SET title_ar='المؤتمر الإفريقي الفرنسي: برازافيل 30 يناير–8 فبراير 1944', description='وصف ببليوغرافي: المؤتمر الإفريقي الفرنسي: برازافيل 30 يناير–8 فبراير 1944. مجموعة أعمال ووثائق المؤتمر الذي أعاد صياغة سياسة فرنسا في إفريقيا الاستوائية خلال الحرب العالمية الثانية، بما في ذلك الإدارة والتعليم والعمل والتمثيل. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مجموعة أعمال ووثائق المؤتمر الذي أعاد صياغة سياسة فرنسا في إفريقيا الاستوائية خلال الحرب العالمية الثانية، بما في ذلك الإدارة والتعليم والعمل والتمثيل.', notable_quote='«La Conférence africaine française : Brazzaville, 30 janvier-8 février 1944»', quote_page='1', author=COALESCE('Actes officiels',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000045';
