UPDATE materials SET title_ar='بحث في شعب ولغة الباندا', description='وصف ببليوغرافي: بحث في شعب ولغة الباندا. وصف لغوي وإثنوغرافي استعماري للباندا، مفيد لدراسة تصنيفات اللغة والسكان في إفريقيا الوسطى مع ضرورة قراءته نقديًا ضمن سياق إنتاجه الاستعماري. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='وصف لغوي وإثنوغرافي استعماري للباندا، مفيد لدراسة تصنيفات اللغة والسكان في إفريقيا الوسطى مع ضرورة قراءته نقديًا ضمن سياق إنتاجه الاستعماري.', notable_quote='«Essai sur le peuple et la langue banda»', quote_page='1', author=COALESCE('G. Toqué',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000046';
