UPDATE materials SET title_ar='وضع الإقليم العسكري لتشاد في مطلع 1912', description='وصف ببليوغرافي: وضع الإقليم العسكري لتشاد في مطلع 1912. تقرير عن الوضع العسكري والإداري في الإقليم العسكري لتشاد، ويعرض الانتشار والطرق والسلطات المحلية وتقييم الإدارة الفرنسية بعد احتلال وداي. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تقرير عن الوضع العسكري والإداري في الإقليم العسكري لتشاد، ويعرض الانتشار والطرق والسلطات المحلية وتقييم الإدارة الفرنسية بعد احتلال وداي.', notable_quote='«La situation du territoire militaire du Tchad au début de 1912»', quote_page='1', author=COALESCE('Victor-Emmanuel Largeau',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000045';
