UPDATE materials SET title_ar='من الجزائر إلى الكونغو عبر تشاد', description='وصف ببليوغرافي: من الجزائر إلى الكونغو عبر تشاد. سرد رحلة تجارية وعلمية تعبر المجال الصحراوي وحوض تشاد، وتصف الطرق والموارد والمراكز والسكان من منظور رحلات القرن التاسع عشر. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='سرد رحلة تجارية وعلمية تعبر المجال الصحراوي وحوض تشاد، وتصف الطرق والموارد والمراكز والسكان من منظور رحلات القرن التاسع عشر.', notable_quote='«De l’Algérie au Congo par le Tchad»', quote_page='1', author=COALESCE('Capitaine Métois',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000046';
