UPDATE materials SET title_ar='احتلال حوض تشاد والعمليات العسكرية لسنة 1900', description='وصف ببليوغرافي: احتلال حوض تشاد والعمليات العسكرية لسنة 1900. عرض للعمليات العسكرية التي قادت إلى بسط السيطرة الفرنسية على حوض تشاد، مع خرائط ومواقع ووقائع الحملة في نهاية القرن التاسع عشر. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='عرض للعمليات العسكرية التي قادت إلى بسط السيطرة الفرنسية على حوض تشاد، مع خرائط ومواقع ووقائع الحملة في نهاية القرن التاسع عشر.', notable_quote='«L’occupation du bassin du Tchad et les opérations militaires de 1900»', quote_page='1', author=COALESCE('Georges Bruel',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000047';
