UPDATE materials SET title_ar='في تشاد: ثلاث سنوات مع السنوسيين والودايين والكردي', description='وصف ببليوغرافي: في تشاد: ثلاث سنوات مع السنوسيين والودايين والكردي. رحلة ومذكرات ميدانية عن تشاد والسنوسيين ووداي والكردي، تجمع الوصف الجغرافي والملاحظات السياسية والاحتكاك اليومي بالمجتمعات المحلية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='رحلة ومذكرات ميدانية عن تشاد والسنوسيين ووداي والكردي، تجمع الوصف الجغرافي والملاحظات السياسية والاحتكاك اليومي بالمجتمعات المحلية.', notable_quote='«Au Tchad : trois ans chez les Senoussistes, les Ouaddaïens et les Kirdis»', quote_page='1', author=COALESCE('Capitaine Cornet',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000048';
