UPDATE materials SET title_ar='السياسة الإسلامية في إفريقيا الغربية الفرنسية', description='وصف ببليوغرافي: السياسة الإسلامية في إفريقيا الغربية الفرنسية. عرض للسياسة الاستعمارية تجاه الإسلام والمسلمين في إفريقيا الغربية الفرنسية، وهو مصدر مقارن لفهم الأدوات الإدارية التي امتدت إلى تشاد. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='عرض للسياسة الاستعمارية تجاه الإسلام والمسلمين في إفريقيا الغربية الفرنسية، وهو مصدر مقارن لفهم الأدوات الإدارية التي امتدت إلى تشاد.', notable_quote='«La politique musulmane dans l’Afrique occidentale française»', quote_page='1', author=COALESCE('J. Quellien',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000047';
