UPDATE materials SET title_ar='بحث في شعب ولغة السارا', description='وصف ببليوغرافي: بحث في شعب ولغة السارا. دراسة لغوية وإثنوغرافية عن السارا، تتضمن مفردات وتصنيفات وملاحظات عن المجتمع واللغة ضمن المعرفة الاستعمارية المبكرة. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='دراسة لغوية وإثنوغرافية عن السارا، تتضمن مفردات وتصنيفات وملاحظات عن المجتمع واللغة ضمن المعرفة الاستعمارية المبكرة.', notable_quote='«Essai sur le peuple et la langue sara»', quote_page='1', author=COALESCE('Maurice Delafosse',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000048';
