UPDATE materials SET title_ar='موجز عام للغات إفريقيا، ولا سيما إفريقيا الفرنسية', description='وصف ببليوغرافي: موجز عام للغات إفريقيا، ولا سيما إفريقيا الفرنسية. محاولة تصنيف ومقارنة لغات إفريقيا، تكشف مناهج المعرفة اللغوية الاستعمارية ومفرداتها في مطلع القرن العشرين. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='محاولة تصنيف ومقارنة لغات إفريقيا، تكشف مناهج المعرفة اللغوية الاستعمارية ومفرداتها في مطلع القرن العشرين.', notable_quote='«Esquisse générale des langues de l’Afrique et plus particulièrement de l’Afrique française»', quote_page='1', author=COALESCE('Maurice Delafosse',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000049';
