UPDATE materials SET title_ar='فرنسا والإسلاموية', description='وصف ببليوغرافي: فرنسا والإسلاموية. نص سياسي استعماري عن علاقة فرنسا بالإسلام والحركات الإسلامية، مهم بوصفه شاهدًا على لغة السياسة الفرنسية قبل التوسع في حوض تشاد. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='نص سياسي استعماري عن علاقة فرنسا بالإسلام والحركات الإسلامية، مهم بوصفه شاهدًا على لغة السياسة الفرنسية قبل التوسع في حوض تشاد.', notable_quote='«France et islamisme»', quote_page='1', author=COALESCE('Comte de Polignac',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000050';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000050';
