UPDATE materials SET title_ar='رحلة تجارية وعلمية إلى حوض تشاد', description='وصف ببليوغرافي: رحلة تجارية وعلمية إلى حوض تشاد. سجل رحلة يستعرض المسالك والاقتصاد والبيئة والمجتمعات في حوض تشاد قبل اكتمال الاحتلال الفرنسي. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='سجل رحلة يستعرض المسالك والاقتصاد والبيئة والمجتمعات في حوض تشاد قبل اكتمال الاحتلال الفرنسي.', notable_quote='«Voyage commercial et scientifique au bassin du Tchad»', quote_page='1', author=COALESCE('Ferdinand de Béhagle',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000049';
DELETE FROM materials_fts WHERE ark='ARC-TD-BOK-000049';
