UPDATE materials SET title_ar='مشروع احتلال واستكشاف وداي', description='وصف ببليوغرافي: مشروع احتلال واستكشاف وداي. وثيقة تخطيطية تكشف تصورات الجيش الفرنسي لاحتلال وداي واستكشافه، بما في ذلك الأهداف والطرق والموارد وموازين القوى. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='وثيقة تخطيطية تكشف تصورات الجيش الفرنسي لاحتلال وداي واستكشافه، بما في ذلك الأهداف والطرق والموارد وموازين القوى.', notable_quote='«Projet d’occupation et d’exploration du Ouadaï»', quote_page='1', author=COALESCE('Capitaine Mangin',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000051';
