UPDATE materials SET title_ar='مشروع بعثة إلى وداي', description='وصف ببليوغرافي: مشروع بعثة إلى وداي. مشروع بعثة عسكرية/استكشافية إلى وداي يوضح التحضير الميداني للوجود الفرنسي قبيل الاحتلال المباشر. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مشروع بعثة عسكرية/استكشافية إلى وداي يوضح التحضير الميداني للوجود الفرنسي قبيل الاحتلال المباشر.', notable_quote='«Projet de mission au Ouadaï»', quote_page='1', author=COALESCE('Capitaine Prins',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000050';
DELETE FROM materials_fts WHERE ark='ARC-TD-BOK-000050';
