UPDATE materials SET title_ar='مذكرة عن وداي (1848–1850)', description='وصف ببليوغرافي: مذكرة عن وداي (1848–1850). مذكرة مبكرة عن وداي وأوضاعه السياسية والجغرافية، تمثل معرفة دبلوماسية ولغوية سبقت الاحتلال الفرنسي بعقود. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مذكرة مبكرة عن وداي وأوضاعه السياسية والجغرافية، تمثل معرفة دبلوماسية ولغوية سبقت الاحتلال الفرنسي بعقود.', notable_quote='«Mémoire sur le Waday (1848-1850)»', quote_page='1', author=COALESCE('Fulgence Fresnel',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000051';
