UPDATE materials SET title_ar='Gallica / BnF — فهرس مصادر تشاد (1850–1952)', description='سجل توثيقي لمجموعة كتب Gallica، يشرح طريقة الجمع وإعادة تركيب النسخ من صور IIIF والتحقق من اكتمالها.', summary='فهرس بحثي لنتائج Gallica عن تشاد ووداي وأبشة والإسلام والبعثات، يثبت صفحات Gallica والنسخ الرقمية وعدد الصفحات وملاحظات التحقق.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000052';
