UPDATE materials SET title_ar='Gallica — مصادر منشورة عن دودمورا وجنتيل والسنوسي وتشاد (1910–1912)', description='دليل انتقائي للمصادر المطبوعة التي تكمل مواد حوض تشاد في العقدين الأولين من القرن العشرين.', summary='فهرس لمصادر منشورة في Gallica حول دودمورا وجنتيل ومعاهدة السنوسي ومعركة أدغول والتقارير السياسية لتشاد.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-ART-000010';
