UPDATE materials SET title_ar='خريطة وداي', description='وصف ببليوغرافي: خريطة وداي. خريطة تاريخية للمجال الواداي وطرقه ومواقعه، تحفظ تصورًا جغرافيًا عسكريًا من سنة 1911. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='خريطة تاريخية للمجال الواداي وطرقه ومواقعه، تحفظ تصورًا جغرافيًا عسكريًا من سنة 1911.', notable_quote='«Carte du Ouadaï»', quote_page='1', author=COALESCE('Lieutenant Meunier',author), updated_at=datetime('now') WHERE ark='ARC-TD-MAP-000001';
