UPDATE materials SET title_ar='خريطة وداي، ورقتان', description='وصف ببليوغرافي: خريطة وداي، ورقتان. خريطة عسكرية من ورقتين توضح المجال الواداي في سياق الإدارة الفرنسية سنة 1913، وتفيد في مقارنة الحدود والطرق مع الخرائط الحديثة. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='خريطة عسكرية من ورقتين توضح المجال الواداي في سياق الإدارة الفرنسية سنة 1913، وتفيد في مقارنة الحدود والطرق مع الخرائط الحديثة.', notable_quote='«Carte du Ouadaï (2 feuilles)»', quote_page='1', author=COALESCE('V.-E. Largeau',author), updated_at=datetime('now') WHERE ark='ARC-TD-MAP-000002';
