UPDATE materials SET title_ar='فرويلش — حالة الأعمال المتصلة بتشاد', description='مذكرة ببليوغرافية تضبط ما يمكن نسبته إلى فرويلش وما يحتاج إلى وصول مؤسسي أو حقوق نشر.', summary='قائمة نقدية بأعمال جان كلود فرويلش المتصلة بتشاد، تميز بين الكتب ذات الصلة والنسخ التي لم يتثبت توفرها القانوني الكامل.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000053';
