UPDATE materials SET title_ar='ANOM — فهرس مصادر اللغة العربية والإسلام ووداي وأبشة', description='دليل بحث في كتالوج ANOM يربط الموضوعات التشادية بمراجع الحفظ الرسمية.', summary='جرد موضوعي لمواد ANOM المتعلقة بالعربية والتعليم والإسلام ووداي وأبشة، مع أرقام السلاسل والملفات وحدود الإتاحة.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000055';
