UPDATE materials SET title_ar='كلية أبشة الفرنسية العربية — مضمون ملف GG AEF 5D 269', description='ملخص وثائقي لتاريخ التعليم العربي والفرنسي في أبشة مع تنبيه إلى أن الملف الأصلي غير مرقمن.', summary='يعرض مضمون وثائق ملف كلية أبشة الفرنسية العربية، ويميز بين الوصف الأرشيفي الأصلي والنصوص المنشورة كاملة في مصادر جامعية.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000056';
