UPDATE materials SET title_ar='مذكرات ودراسة دليسل عن مشروع وداي', description='وصف ببليوغرافي: مذكرات ودراسة دليسل عن مشروع وداي. نسخة مرجعية مرتبطة بمذكرات ومشروع البعثة إلى وداي، محفوظة هنا بوصفها مادة ببليوغرافية/مراجعة لا بوصفها نسخة أصلية مؤكدة من الكتاب. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='نسخة مرجعية مرتبطة بمذكرات ومشروع البعثة إلى وداي، محفوظة هنا بوصفها مادة ببليوغرافية/مراجعة لا بوصفها نسخة أصلية مؤكدة من الكتاب.', notable_quote='«Mémoires — étude de Lisle»', quote_page='1', author=COALESCE('Prins / Étude de Lisle',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000052';
