UPDATE materials SET title_ar='الوثائق العلمية لبعثة تيلو (1906–1909)، المجلد الثاني', description='وصف ببليوغرافي: الوثائق العلمية لبعثة تيلو (1906–1909)، المجلد الثاني. جزء من حصيلة بعثة تيلو العلمية، يضم قياسات وملاحظات ووثائق ميدانية عن الحدود والبيئة والمسالك في حوض تشاد ومناطق النيجر. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='جزء من حصيلة بعثة تيلو العلمية، يضم قياسات وملاحظات ووثائق ميدانية عن الحدود والبيئة والمسالك في حوض تشاد ومناطق النيجر.', notable_quote='«Documents scientifiques de la mission Tilho (1906-1909)»', quote_page='1', author=COALESCE('Jean Tilho',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000059';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000059';
