UPDATE materials SET title_ar='الوثائق العلمية لبعثة تيلو (1906–1909)، المجلد الأول', description='وصف ببليوغرافي: الوثائق العلمية لبعثة تيلو (1906–1909)، المجلد الأول. المجلد الأول من أعمال بعثة تيلو، مصدر أساسي للجغرافيا والخرائط والملاحظات العلمية التي رافقت مهمة ترسيم الحدود والاستكشاف. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='المجلد الأول من أعمال بعثة تيلو، مصدر أساسي للجغرافيا والخرائط والملاحظات العلمية التي رافقت مهمة ترسيم الحدود والاستكشاف.', notable_quote='«Documents scientifiques de la mission Tilho (1906-1909)»', quote_page='1', author=COALESCE('Jean Tilho',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000060';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000060';
