UPDATE materials SET title_ar='رسالة تيلو من مساكوري، 5 أبريل 1913', description='وصف ببليوغرافي: رسالة تيلو من مساكوري، 5 أبريل 1913. مراسلة قصيرة مرتبطة ببعثة تيلو، توثق اتصالًا ميدانيًا من مساكوري وتكمل سجل المهمة في حوض تشاد. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مراسلة قصيرة مرتبطة ببعثة تيلو، توثق اتصالًا ميدانيًا من مساكوري وتكمل سجل المهمة في حوض تشاد.', notable_quote='«Lettre de la mission au Tchad»', quote_page='1', author=COALESCE('Jean Tilho',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000061';
