UPDATE materials SET title_ar='تقرير عن مهمة في إفريقيا، 1917', description='وصف ببليوغرافي: تقرير عن مهمة في إفريقيا، 1917. تقرير موجز عن مهمة تيلو وخبرتها الميدانية، يثبت امتداد العمل العلمي والإداري الفرنسي في إفريقيا الوسطى. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='تقرير موجز عن مهمة تيلو وخبرتها الميدانية، يثبت امتداد العمل العلمي والإداري الفرنسي في إفريقيا الوسطى.', notable_quote='«Compte rendu de sa mission en Afrique»', quote_page='1', author=COALESCE('Jean Tilho',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000062';
