UPDATE materials SET title_ar='رسالة تيلو من ماو، 25 أغسطس 1913', description='وصف ببليوغرافي: رسالة تيلو من ماو، 25 أغسطس 1913. مراسلة ميدانية من ماو ضمن وثائق البعثة، تتيح تتبع الحركة والاتصال والعمل العلمي في مناطق تشاد الداخلية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مراسلة ميدانية من ماو ضمن وثائق البعثة، تتيح تتبع الحركة والاتصال والعمل العلمي في مناطق تشاد الداخلية.', notable_quote='«Lettre sur la mission au Tchad»', quote_page='1', author=COALESCE('Jean Tilho',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000063';
