UPDATE materials SET title_ar='رسالة تيلو من ماو، 4 نوفمبر 1912', description='وصف ببليوغرافي: رسالة تيلو من ماو، 4 نوفمبر 1912. رسالة مبكرة من ماو تسجل جانبًا من عمل بعثة تيلو في مرحلة إعادة تنظيم المجال العسكري والحدودي. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='رسالة مبكرة من ماو تسجل جانبًا من عمل بعثة تيلو في مرحلة إعادة تنظيم المجال العسكري والحدودي.', notable_quote='«Nouvelles de la mission au Tchad»', quote_page='1', author=COALESCE('Jean Tilho',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000064';
