UPDATE materials SET title_ar='ل. روسرو دو ملان — في منطقة تشاد مع بعثة تيلو', description='نص رحلي مستخرج من نسخة مصورة، يعرض مشاهد الطريق والبعثة والبيئة التشادية مع إبقاء حالة OCR معلنة.', summary='تفريغ OCR لمقال روسرو دو ملان عن منطقة تشاد وبعثة تيلو من مجلة Le Tour du monde، مع إحالة إلى الفهرس الأصلي وبيان أن النص مستخرج آليًا.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000065';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000065';
