UPDATE materials SET title_ar='الجرد التفصيلي لأرشيف هنري غورود 399PAAP', description='وصف ببليوغرافي: الجرد التفصيلي لأرشيف هنري غورود 399PAAP. أداة بحث رسمية لفهرس أرشيف هنري غورود، تغطي ملفات 1879–1993 وتتيح تحديد المراسلات والتقارير والوثائق المتعلقة بتشاد والإدارة الاستعمارية. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='أداة بحث رسمية لفهرس أرشيف هنري غورود، تغطي ملفات 1879–1993 وتتيح تحديد المراسلات والتقارير والوثائق المتعلقة بتشاد والإدارة الاستعمارية.', notable_quote='«Répertoire numérique détaillé des archives d’Henri Gouraud»', quote_page='1', author=COALESCE('Françoise Aujogue؛ Sophie Champenois',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000066';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000066';
