UPDATE materials SET title_ar='ذكريات من زندر وتشاد', description='وصف ببليوغرافي: ذكريات من زندر وتشاد. مذكرات وشهادات عن تجربة هنري غورود في زندر وتشاد، تسجل رؤية مسؤول عسكري وإداري فرنسي لمسار الاحتلال والإدارة. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='مذكرات وشهادات عن تجربة هنري غورود في زندر وتشاد، تسجل رؤية مسؤول عسكري وإداري فرنسي لمسار الاحتلال والإدارة.', notable_quote='«Zinder-Tchad : souvenirs»', quote_page='1', author=COALESCE('Henri Gouraud',author), updated_at=datetime('now') WHERE ark='ARC-TD-BOK-000053';
DELETE FROM materials_fts WHERE ark='ARC-TD-BOK-000053';
