UPDATE materials SET title_ar='أداة البحث الأرشيفية — وصف الملف PA-AP/399', description='وثيقة مرجعية لا تلخص حدثًا واحدًا، بل تتيح الوصول المنهجي إلى مراسلات وتقارير أرشيف غورود.', summary='نقل حرفي لوصف أداة البحث الرسمية لأرشيف هنري غورود، مع نطاق التواريخ والجهة الحافظة والرابط الدائم.', notable_quote=NULL, quote_page=NULL, author=COALESCE(NULL,author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000067';
