UPDATE materials SET title_ar='من النيجر إلى النيل، المجلد الأول', description='وصف ببليوغرافي: من النيجر إلى النيل، المجلد الأول. رحلة استكشافية عبر إفريقيا الداخلية، توثق الطرق والبيئات والمجتمعات بين النيجر والنيل وتقدم مادة مقارنة لحوض تشاد. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='رحلة استكشافية عبر إفريقيا الداخلية، توثق الطرق والبيئات والمجتمعات بين النيجر والنيل وتقدم مادة مقارنة لحوض تشاد.', notable_quote='«From the Niger to the Nile»', quote_page='1', author=COALESCE('Boyd Alexander',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000068';
