UPDATE materials SET title_ar='من النيجر إلى النيل، المجلد الثاني', description='وصف ببليوغرافي: من النيجر إلى النيل، المجلد الثاني. استكمال رحلة ألكسندر، مع مشاهدات جغرافية وحيوانية وإثنوغرافية وملاحق عن المجال الواقع بين النيجر والنيل. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='استكمال رحلة ألكسندر، مع مشاهدات جغرافية وحيوانية وإثنوغرافية وملاحق عن المجال الواقع بين النيجر والنيل.', notable_quote='«From the Niger to the Nile»', quote_page='1', author=COALESCE('Boyd Alexander',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000069';
DELETE FROM materials_fts WHERE ark='ARC-TD-DOC-000069';
