UPDATE materials SET title_ar='من الهوسا لاند إلى مصر', description='وصف ببليوغرافي: من الهوسا لاند إلى مصر. سرد رحلة عبر غرب ووسط إفريقيا نحو مصر، يتقاطع مع فضاء كانم–برنو وحوض تشاد ويقدم ملاحظات عن المجتمعات والطرق والاتصال الديني. النسخة المحفوظة في سِجِل مرتبطة بالمصدر الخارجي الموثق في بيانات المادة.', summary='سرد رحلة عبر غرب ووسط إفريقيا نحو مصر، يتقاطع مع فضاء كانم–برنو وحوض تشاد ويقدم ملاحظات عن المجتمعات والطرق والاتصال الديني.', notable_quote='«From Hausaland to Egypt»', quote_page='1', author=COALESCE('H. K. Kumm',author), updated_at=datetime('now') WHERE ark='ARC-TD-DOC-000070';
